from typing import List


def find_budget_pair(prices: List[int], budget: int) -> List[int]:
    """Return the 1-indexed pair (smallest first index) summing to budget, else [-1, -1]."""
    lo, hi = 0, len(prices) - 1
    while lo < hi:
        s = prices[lo] + prices[hi]  # Python ints are arbitrary precision: no overflow
        if s == budget:
            return [lo + 1, hi + 1]  # convert both to 1-indexed positions
        if s < budget:
            lo += 1  # prices[hi] is the biggest partner left, so prices[lo] is unusable
        else:
            hi -= 1  # prices[lo] is the smallest partner left, so prices[hi] is unusable
    return [-1, -1]

