import java.util.*;

public class Solution {
    public int[] findBudgetPair(int[] prices, long budget) {
        int lo = 0, hi = prices.length - 1;
        while (lo < hi) {
            // widen to long: prices[lo] + prices[hi] can reach 2 * 10^9 and overflow int
            long s = (long) prices[lo] + (long) prices[hi];
            if (s == budget) {
                return new int[]{lo + 1, hi + 1}; // 1-indexed positions
            }
            if (s < budget) {
                lo++; // biggest available partner still too small -> discard prices[lo]
            } else {
                hi--; // smallest available partner already too big -> discard prices[hi]
            }
        }
        return new int[]{-1, -1};
    }
}

