#include <vector>

class Solution {
public:
    std::vector<int> findBudgetPair(const std::vector<int>& prices, long long budget) {
        int lo = 0, hi = static_cast<int>(prices.size()) - 1;
        while (lo < hi) {
            // cast one operand: int + int would overflow before the assignment to long long
            long long s = static_cast<long long>(prices[lo]) + prices[hi];
            if (s == budget) {
                return {lo + 1, hi + 1};  // 1-indexed positions
            }
            if (s < budget) {
                ++lo;  // largest remaining partner still too small -> prices[lo] is dead
            } else {
                --hi;  // smallest remaining partner already too big -> prices[hi] is dead
            }
        }
        return {-1, -1};
    }
};

