public class Solution {
    public String compressLog(String s) {
        int n = s.length();
        StringBuilder out = new StringBuilder(); // mutable buffer: append is amortized O(1)
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && s.charAt(j) == s.charAt(i)) { // walk to the end of the run
                j++;
            }
            int run = j - i;
            out.append(s.charAt(i));
            if (run >= 2) {
                out.append(run); // append(int) writes all decimal digits, e.g. 12 -> "12"
            }
            i = j; // jump past the finished run
        }
        return out.length() < n ? out.toString() : s; // strictly shorter or keep original
    }
}

