#include <string>

class Solution {
public:
    std::string compressLog(const std::string& s) {
        const int n = static_cast<int>(s.size());
        std::string out;
        out.reserve(s.size());  // upper bound guess; avoids most reallocations
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && s[j] == s[i]) {  // extend to the end of the maximal run
                ++j;
            }
            const int run = j - i;
            out.push_back(s[i]);
            if (run >= 2) {
                out += std::to_string(run);  // multi-digit safe, e.g. 12 -> "12"
            }
            i = j;  // jump past the finished run
        }
        return out.size() < s.size() ? out : s;  // strictly shorter or keep original
    }
};

