import java.util.*;

public class Solution {
    public int longestDistinctWindow(int[] intents) {
        Map<Integer, Integer> lastSeen = new HashMap<>(); // value -> most recent index
        int left = 0, best = 0;
        for (int right = 0; right < intents.length; right++) {
            int value = intents[right];
            Integer prev = lastSeen.get(value);
            if (prev != null && prev >= left) {
                // duplicate lies inside the window: jump past it; prev < left means stale
                left = prev + 1;
            }
            lastSeen.put(value, right);
            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

