#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    int longestDistinctWindow(const std::vector<int>& intents) {
        std::unordered_map<int, int> lastSeen;  // value -> most recent index
        int left = 0, best = 0;
        const int n = static_cast<int>(intents.size());
        for (int right = 0; right < n; ++right) {
            const int value = intents[right];
            auto it = lastSeen.find(value);
            if (it != lastSeen.end() && it->second >= left) {
                // duplicate is inside the window: jump past it (stale entries are ignored)
                left = it->second + 1;
            }
            lastSeen[value] = right;
            best = std::max(best, right - left + 1);
        }
        return best;
    }
};

