import java.util.*;

public class Solution {
    public long countTargetSubarrays(int[] delta, long target) {
        // keys are 64-bit: prefix sums reach +/- 2 * 10^9 and would overflow int
        Map<Long, Integer> count = new HashMap<>();
        count.put(0L, 1); // the empty prefix
        long running = 0L;
        long ans = 0L;    // answer can reach ~2 * 10^10, so it must be long
        for (int v : delta) {
            running += v;
            ans += count.getOrDefault(running - target, 0); // QUERY before inserting
            count.merge(running, 1, Integer::sum);
        }
        return ans;
    }
}

