#include <vector>
#include <unordered_map>

class Solution {
public:
    long long countTargetSubarrays(const std::vector<int>& delta, long long target) {
        // 64-bit keys: prefix sums reach +/- 2 * 10^9
        std::unordered_map<long long, int> count;
        count[0] = 1;  // the empty prefix
        long long running = 0;
        long long ans = 0;  // answer can reach ~2 * 10^10
        for (int v : delta) {
            running += v;
            auto it = count.find(running - target);
            if (it != count.end()) {
                ans += it->second;  // QUERY before inserting the current prefix
            }
            ++count[running];
        }
        return ans;
    }
};

