import java.util.*;

public class Solution {
    public int[][] mergeWindows(int[][] windows) {
        if (windows.length == 0) {
            return new int[0][0];
        }
        // sort by start; comparison by subtraction could overflow, so use Integer.compare
        Arrays.sort(windows, (a, b) -> Integer.compare(a[0], b[0]));
        List<int[]> merged = new ArrayList<>();
        int curStart = windows[0][0], curEnd = windows[0][1];
        for (int i = 1; i < windows.length; i++) {
            int s = windows[i][0], e = windows[i][1];
            if (s <= curEnd) {
                // '<=' merges touching intervals; max handles nested ones
                curEnd = Math.max(curEnd, e);
            } else {
                merged.add(new int[]{curStart, curEnd}); // group is final
                curStart = s;
                curEnd = e;
            }
        }
        merged.add(new int[]{curStart, curEnd}); // flush the last open group
        return merged.toArray(new int[0][]);
    }
}

