#include <vector>
#include <algorithm>

class Solution {
public:
    // taken by value so the caller's vector is not reordered
    std::vector<std::vector<int>> mergeWindows(std::vector<std::vector<int>> windows) {
        if (windows.empty()) {
            return {};
        }
        std::sort(windows.begin(), windows.end(),
                  [](const std::vector<int>& a, const std::vector<int>& b) {
                      return a[0] < b[0];  // sort by start
                  });
        std::vector<std::vector<int>> merged;
        int curStart = windows[0][0], curEnd = windows[0][1];
        for (std::size_t i = 1; i < windows.size(); ++i) {
            const int s = windows[i][0], e = windows[i][1];
            if (s <= curEnd) {
                // '<=' merges touching intervals; max handles nested ones
                curEnd = std::max(curEnd, e);
            } else {
                merged.push_back({curStart, curEnd});  // group is final
                curStart = s;
                curEnd = e;
            }
        }
        merged.push_back({curStart, curEnd});  // flush the last open group
        return merged;
    }
};

