public class Solution {
    public long maxRunWithOneSkip(int[] scores) {
        // safe sentinel: dividing by 4 guarantees NEG + scores[i] cannot underflow
        final long NEG = Long.MIN_VALUE / 4;
        long keep = scores[0]; // best run ending here, no deletion used
        long drop = NEG;       // best run ending here, deletion already spent
        long best = scores[0];
        for (int i = 1; i < scores.length; i++) {
            long v = scores[i];
            // branch 1: delete v and inherit the deletion-free run ending at i-1 (non-empty)
            // branch 2: deletion already spent, extend that run by v
            long newDrop = Math.max(keep, drop + v);
            long newKeep = Math.max(v, keep + v);   // ordinary Kadane step
            keep = newKeep;                          // assign only after BOTH are computed
            drop = newDrop;
            best = Math.max(best, Math.max(keep, drop));
        }
        return best;
    }
}

